      "additionalProperties": false,
      "description": "One OHLCV bar.",
      "properties": {
        "c": {
          "description": "Close price.",
          "format": "double",
          "type": "number"
        },
        "h": {
          "description": "High price.",
          "format": "double",
          "type": "number"
        },
        "l": {
          "description": "Low price.",
          "format": "double",
          "type": "number"
